// Articles contain deliberately separate workflows, evidence models, examples, and outcomes.
const inventory=[];
for (const a of articles) {
  const sourceList = a.sources.map(([name,url])=>`- [${name}](${url})`).join('\n');
  const body = a.sections.map(([h,p])=>`## ${h}\n\n${p}`).join('\n\n');
  const practical = `## A practical launch sequence\n\nPilot ${a.title.toLowerCase()} with a small, representative set rather than opening every record at once. Have the accountable owners approve the input sources, ordinary actions, stop conditions, access, evidence standard, and escalation destinations. Review the first outputs record by record. Include at least one incomplete case and one conflict so the team learns the waiting state instead of treating throughput as the only objective. Expand only after reviewers can reproduce outcomes from the saved evidence. Keep questions and corrections as inputs to the next instruction version, with an effective date and owner.\n\nAt the end of each ${a.service.replaceAll('-',' ')} work period, the queue should tell the next authorized person what is known, which source supports it, what remains uncertain, who owns the next decision, and when follow-up is due. That handoff is especially important across time zones. It prevents silence from becoming assumed approval and lets a Philippines-based team contribute useful continuity without absorbing authority that belongs to the client. Offshore Outsourcing Company can help translate this specific ${a.slug.replaceAll('-',' ')} lane into a role brief, work sample, access plan, and review cadence; the client’s qualified owners still control policy and consequential decisions.`;
  const checkpoint = `## Questions for the first owner review\n\nBefore approving this ${a.title.toLowerCase()} workflow, ask who controls the starting record, which fields the coordinator may change, which event stops ordinary processing, and which person can release the next consequential action. Ask how the reviewer will distinguish a missing input from a disputed fact, where superseded evidence remains available, and how access will be removed when the assignment changes. Use the first section—“${a.sections[0][0]}”—as the opening work-sample test. Then test an exception drawn from “${a.sections[5][0]}” so candidates demonstrate restraint as well as accuracy. Finally, agree on a weekly sample size, error categories, response clock, and correction owner. The review should reward source use and honest escalation; it should not reward a coordinator for guessing simply to empty the queue.`;
  const sources = `## Sources and limits\n\n${sourceList}\n\nThe references supporting “${a.title}” were checked for the October 2026 drafting cycle and provide current general context. They do not decide the facts, legal duties, accounting treatment, safety result, or contract interpretation for a specific business. Recheck changing requirements and platform guidance before relying on them, and involve qualified advisers where this ${a.service.replaceAll('-',' ')} workflow crosses regulated or professional judgment.`;
  const raw = `---\nslug: "${a.slug}"\ndatePublished: "${date}"\npublishedAt: "${date}T12:00:00.000Z"\nupdatedAt: "${date}T12:00:00.000Z"\n---\n\n# ${a.title}\n\n*October 11, 2026*\n\n${a.excerpt} The operating goal is a reviewable administrative lane: approved sources enter, routine checks happen under written rules, exceptions remain visible, and the person with authority makes the decision.\n\n${body}\n\n${checkpoint}\n\n${practical}\n\n${sources}\n`;
  fs.writeFileSync(path.join('content/blog',`${a.slug}.md`),raw);
  const substantive=raw.replace(/^---[\s\S]*?---\s*/,'').replace(/^#.*$/m,'').replace(/^\*October 11, 2026\*$/m,'').trim();
  inventory.push({slug:a.slug,title:a.title,topic:a.excerpt,service:a.service,bodyWords:(substantive.match(/\b[\w’-]+\b/g)||[]).length,contentHash:crypto.createHash('sha256').update(substantive).digest('hex'),sources:a.sources.map(([title,url])=>({title,url,checkedDate:date})),actualPublicationDate:null,liveUrl:`https://offshoreoutsourcingcompany.com/blog/${a.slug}`});
}
